package com.basssg.thaidailynews;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Bitmap;import android.webkit.WebView;import android.widget.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
public class SmokeInstrumentation extends Instrumentation {
    @Override public void onCreate(Bundle arguments){super.onCreate(arguments);start();}
    private void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    private String js(Activity activity,String script)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] result={""};runOnMainSync(()->{android.view.View root=activity.getWindow().getDecorView();WebView web=findWeb(root);if(web==null){done.countDown();return;}web.evaluateJavascript(script,value->{result[0]=value;done.countDown();});});require(done.await(10,TimeUnit.SECONDS),"JavaScript timed out");return result[0];}
    private WebView findWeb(android.view.View view){if(view instanceof WebView)return (WebView)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){WebView found=findWeb(group.getChildAt(i));if(found!=null)return found;}}return null;}
    private void screenshot(String name)throws Exception{File dir=new File(getTargetContext().getExternalFilesDir(null),"qa");dir.mkdirs();Bitmap image=getUiAutomation().takeScreenshot();require(image!=null,"Screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private int photos(android.view.View view){int count=view.getId()==R.id.story_photo&&view instanceof ImageView&&((ImageView)view).getDrawable()!=null?1:0;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)count+=photos(group.getChildAt(i));}return count;}
    private <T extends android.view.View> T find(android.view.View view,Class<T> type){if(type.isInstance(view)&&!(type==Button.class&&view instanceof CompoundButton))return type.cast(view);if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){T found=find(group.getChildAt(i),type);if(found!=null)return found;}}return null;}
    @Override public void onStart(){Bundle result=new Bundle();try{
        Context context=getTargetContext();require(!NewsRepository.trustedApiHost("https://script.google.com.evil.example/"),"Redirect trust boundary");require(!NewsRepository.trustedApiHost("http://script.google.com/"),"HTTPS required");
        JSONObject response=null;for(int attempt=0;attempt<5;attempt++){try{response=NewsRepository.refresh(context,false);if(response.optBoolean("ok"))break;}catch(java.io.IOException unavailable){if(attempt==4)throw unavailable;}Thread.sleep(3000);}require(response!=null&&response.optBoolean("ok"),"Live GAS response");JSONArray news=NewsRepository.cached(context).optJSONArray("items");require(news!=null&&news.length()>0,"Real news cache is empty");
        JSONObject filter=new JSONObject().put("categories",new JSONArray().put("tech"));require(!NewsRepository.matches(new JSONObject().put("category_id","crime"),filter),"Notification category filter");
        Activity activity=startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        boolean ready=false;for(int i=0;i<40;i++){if(!"0".equals(js(activity,"document.querySelectorAll('.news-card').length"))&&"true".equals(js(activity,"!!document.querySelector('.news-card')"))){ready=true;break;}Thread.sleep(1000);}require(ready,"News UI failed to load");
        boolean photoReady=false;for(int i=0;i<30;i++){if("true".equals(js(activity,"!!document.querySelector('.hero-photo img')&&document.querySelector('.hero-photo img').complete&&document.querySelector('.hero-photo img').naturalWidth>80"))){photoReady=true;break;}Thread.sleep(1000);}require(photoReady,"Hero photograph failed to load in Android: "+js(activity,"JSON.stringify({count:document.querySelectorAll('img.news-image').length,images:Array.from(document.querySelectorAll('img.news-image')).slice(0,3).map(img=>({src:img.src,complete:img.complete,width:img.naturalWidth})),fresh:document.querySelector('#freshness')?.textContent})"));Thread.sleep(300);screenshot("android-home");
        js(activity,"document.querySelector('[data-open]').click(); true");Thread.sleep(500);require("false".equals(js(activity,"document.querySelector('#articleDrawer').hidden")),"Article drawer");screenshot("android-article");
        js(activity,"document.querySelector('#articleContent [data-save]').click(); true");require(NewsRepository.bookmarks(context).length()>0,"Bookmark sync for widgets");
        js(activity,"window.TDN_BACK(); document.querySelector('[data-action=settings]').click(); true");Thread.sleep(500);require("true".equals(js(activity,"document.querySelector('#settingsDialog').open")),"Settings dialog");screenshot("android-settings");
        require(!WidgetImageCache.safeUrl("http://www.bbc.com/photo.jpg")&&!WidgetImageCache.safeUrl("https://127.0.0.1/a.jpg")&&!WidgetImageCache.safeUrl("https://localhost/a.jpg")&&!WidgetImageCache.safeUrl("https://user@www.bbc.com/a.jpg"),"Widget photo URL boundary");
        java.util.List<JSONObject> candidates=new java.util.ArrayList<>();for(int i=0;i<news.length()&&candidates.size()<10;i++){JSONObject item=news.optJSONObject(i);if(item!=null&&WidgetImageCache.safeUrl(item.optString("image_url")))candidates.add(item);}
        NewsRepository.IO.submit(()->WidgetImageCache.preload(context,candidates)).get(45,TimeUnit.SECONDS);
        JSONArray pictured=new JSONArray();for(JSONObject item:candidates){Bitmap bitmap=WidgetImageCache.get(context,item.optString("image_url"),true);if(bitmap!=null){require(bitmap.getWidth()==320&&bitmap.getHeight()==200&&bitmap.getAllocationByteCount()<=256000,"Widget thumbnail memory bound");bitmap.recycle();pictured.put(item);if(pictured.length()==3)break;}}
        require(pictured.length()==3,"Three real publisher widget photos unavailable");NewsRepository.prefs(context).edit().putString("bookmarks",pictured.toString()).putString("widget_-1",new JSONObject().put("mode","saved").put("showImages",true).toString()).apply();
        runOnMainSync(()->{for(String kind:new String[]{"small","medium","large"}){for(int height:new int[]{110,146,285}){Bundle options=new Bundle();options.putInt(android.appwidget.AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,height);android.view.View widget=NewsWidgetProvider.createViews(context,-1,kind,options).apply(context,new FrameLayout(context));require(photos(widget)>0,"Cached/offline photo missing "+kind+"/"+height);}}});
        NewsRepository.prefs(context).edit().putString("widget_-1",new JSONObject().put("mode","saved").put("showImages",false).toString()).apply();
        runOnMainSync(()->{android.view.View widget=NewsWidgetProvider.createViews(context,-1,"large",new Bundle()).apply(context,new FrameLayout(context));require(photos(widget)==0,"Per-widget photo opt-out");require(((TextView)widget.findViewById(R.id.story_title)).getText().length()>0,"Text remains when photos disabled");});
        JSONObject noPhoto=new JSONObject(pictured.getJSONObject(0).toString());noPhoto.remove("image_url");NewsRepository.prefs(context).edit().putString("bookmarks",new JSONArray().put(noPhoto).toString()).putString("widget_-1",new JSONObject().put("mode","saved").put("showImages",true).toString()).apply();
        runOnMainSync(()->{android.view.View widget=NewsWidgetProvider.createViews(context,-1,"small",new Bundle()).apply(context,new FrameLayout(context));require(photos(widget)==0&&((TextView)widget.findViewById(R.id.story_title)).getText().length()>0,"Story without a photo remains readable");});NewsRepository.prefs(context).edit().putString("bookmarks",pictured.toString()).apply();
        android.appwidget.AppWidgetManager manager=android.appwidget.AppWidgetManager.getInstance(context);android.appwidget.AppWidgetHost host=new android.appwidget.AppWidgetHost(context,220);int[] ids=new int[3];Class<?>[] providers={SmallWidget.class,MediumWidget.class,LargeWidget.class};
        getUiAutomation().adoptShellPermissionIdentity("android.permission.BIND_APPWIDGET");try{for(int i=0;i<3;i++){ids[i]=host.allocateAppWidgetId();Bundle options=new Bundle();options.putInt(android.appwidget.AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,i==0?146:i==1?128:285);options.putInt(android.appwidget.AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,i==0?165:350);require(manager.bindAppWidgetIdIfAllowed(ids[i],new ComponentName(context,providers[i]),options),"Native widget binding "+i);NewsRepository.prefs(context).edit().putString("widget_"+ids[i],new JSONObject().put("mode","saved").put("showImages",true).put("theme",i==2?"light":"dark").toString()).apply();}}finally{getUiAutomation().dropShellPermissionIdentity();}
        NewsWidgetProvider.updateAll(context);
        Activity preview=startActivitySync(new Intent(context,WidgetPreviewActivity.class).putExtra("widgetIds",ids).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));boolean widgetsReady=false;for(int i=0;i<15;i++){int[] count={0};runOnMainSync(()->count[0]=photos(preview.getWindow().getDecorView()));if(count[0]>=6){widgetsReady=true;break;}Thread.sleep(1000);}require(widgetsReady,"Photos failed to reach native AppWidgetHost");Thread.sleep(300);screenshot("android-widgets");
        runOnMainSync(()->{TextView title=preview.findViewById(R.id.story_title);android.graphics.Rect visible=new android.graphics.Rect();require(title.getGlobalVisibleRect(visible)&&visible.height()>=title.getHeight()-1,"Small widget headline is clipped");});
        Activity configure=startActivitySync(new Intent(context,WidgetConfigActivity.class).putExtra(android.appwidget.AppWidgetManager.EXTRA_APPWIDGET_ID,ids[0]).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(300);screenshot("android-widget-settings");
        runOnMainSync(()->{Switch toggle=find(configure.getWindow().getDecorView(),Switch.class);require(toggle!=null&&toggle.isChecked(),"Widget photo setting defaults on");toggle.setChecked(false);Button done=find(configure.getWindow().getDecorView(),Button.class);require(done!=null,"Widget configuration save action");done.performClick();});
        require(!NewsWidgetProvider.config(context,ids[0]).optBoolean("showImages",true)&&NewsWidgetProvider.config(context,ids[1]).optBoolean("showImages",true),"Native configuration saves per-widget photo choice");NewsRepository.testNotification(context);
        boolean posted=false;for(android.service.notification.StatusBarNotification n:context.getSystemService(NotificationManager.class).getActiveNotifications())if(n.getId()==201)posted=true;require(posted,"Test notification was not posted");getUiAutomation().executeShellCommand("cmd statusbar expand-notifications").close();Thread.sleep(700);screenshot("notifications");
        host.deleteHost();result.putString("stream","TDN_SMOKE_OK: live GAS, app shell, publisher photos, article, bookmarks, settings, three native AppWidgetHost sizes with offline thumbnails, photo opt-out and missing-image fallback, bounded bitmap memory, notification filters and HTTPS validation passed.\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){try{screenshot("android-failure");}catch(Exception ignored){}result.putString("stream","TDN_SMOKE_FAILED: "+error+"\n");finish(1,result);}}
}
